1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type Project = { id: number; name: string; clientId: number; clientName: string };
11	type Invoice = {
12	  id: number;
13	  projectId: number;
14	  amount: number;
15	  status: string;
16	  issuedDate: string;
17	  dueDate: string;
18	};
19	type Task = { id: number; projectId: number; title: string; done: boolean };
20	
21	type LineItem = {
22	  id: number;
23	  invoiceId: number;
24	  description: string;
25	  qty: number;
26	  unitPrice: number;
27	};
28	
29	function money(amount: number): string {
30	  return `$${Number(amount).toFixed(2)}`;
31	}
32	
33	// One charge line while it is being edited on screen: the fields are held as raw strings so the
34	// inputs stay controlled and the total can recompute live as they change.
35	type EditItem = { id: number; description: string; qty: string; unitPrice: string };
36	
37	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
38	// many, price each), the total worked out for you, and a form to add another line. Each line can be
39	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
40	// own line-item state, scoped to the one invoice it is showing.
41	function InvoiceDetail({
42	  invoiceId,
43	  onChange,
44	  onClose,
45	}: {
46	  invoiceId: number;
47	  onChange: () => void;
48	  onClose: () => void;
49	}) {
50	  const [items, setItems] = useState<EditItem[]>([]);
51	  const [description, setDescription] = useState('');
52	  const [qty, setQty] = useState('');
53	  const [unitPrice, setUnitPrice] = useState('');
54	
55	  async function load() {
56	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
57	    const rows: LineItem[] = await res.json();
58	    setItems(
59	      rows.map((li) => ({
60	        id: li.id,
61	        description: li.description,
62	        qty: String(li.qty),
63	        unitPrice: String(li.unitPrice),
64	      })),
65	    );
66	  }
67	
68	  useEffect(() => {
69	    void load();
70	  }, [invoiceId]);
71	
72	  function editField(id: number, field: 'description' | 'qty' | 'unitPrice', value: string) {
73	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
74	  }
75	
76	  function amountOf(li: EditItem): number {
77	    const line = Number(li.qty) * Number(li.unitPrice);
78	    return Number.isFinite(line) ? line : 0;
79	  }
80	
81	  async function save(li: EditItem) {
82	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
83	      return;
84	    }
85	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
86	      method: 'POST',
87	      headers: { 'Content-Type': 'application/json' },
88	      body: JSON.stringify({
89	        description: li.description,
90	        qty: Number(li.qty),
91	        unitPrice: Number(li.unitPrice),
92	      }),
93	    });
94	    await load();
95	    onChange();
96	  }
97	
98	  async function remove(id: number) {
99	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
100	    await load();
101	    onChange();
102	  }
103	
104	  async function submit(e: React.FormEvent) {
105	    e.preventDefault();
106	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
107	      return;
108	    }
109	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
110	      method: 'POST',
111	      headers: { 'Content-Type': 'application/json' },
112	      body: JSON.stringify({
113	        description,
114	        qty: Number(qty),
115	        unitPrice: Number(unitPrice),
116	      }),
117	    });
118	    setDescription('');
119	    setQty('');
120	    setUnitPrice('');
121	    await load();
122	    onChange();
123	  }
124	
125	  const total = items.reduce((sum, li) => sum + amountOf(li), 0);
126	
127	  return (
128	    <section data-testid="invoice-detail">
129	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
130	        Back to invoices
131	      </button>
132	
133	      <table data-testid="invoice-lineitems-table">
134	        <tbody>
135	          {items.map((li) => (
136	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
137	              <td>
138	                <input
139	                  data-testid="lineitem-description"
140	                  value={li.description}
141	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
142	                />
143	              </td>
144	              <td>
145	                <input
146	                  data-testid="lineitem-qty"
147	                  value={li.qty}
148	                  onChange={(e) => editField(li.id, 'qty', e.target.value)}
149	                />
150	              </td>
151	              <td>
152	                <input
153	                  data-testid="lineitem-unitprice"
154	                  value={li.unitPrice}
155	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
156	                />
157	              </td>
158	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
159	              <td>
160	                <button
161	                  data-testid={`lineitem-save-${li.id}`}
162	                  type="button"
163	                  onClick={() => save(li)}
164	                >
165	                  Save
166	                </button>
167	                <button
168	                  data-testid={`lineitem-remove-${li.id}`}
169	                  type="button"
170	                  onClick={() => remove(li.id)}
171	                >
172	                  Remove
173	                </button>
174	              </td>
175	            </tr>
176	          ))}
177	        </tbody>
178	      </table>
179	
180	      <p data-testid="invoice-amount">{money(total)}</p>
181	
182	      <form data-testid="lineitem-form" onSubmit={submit}>
183	        <input
184	          data-testid="lineitem-form-description"
185	          placeholder="Description"
186	          value={description}
187	          onChange={(e) => setDescription(e.target.value)}
188	        />
189	        <input
190	          data-testid="lineitem-form-qty"
191	          placeholder="How many"
192	          value={qty}
193	          onChange={(e) => setQty(e.target.value)}
194	        />
195	        <input
196	          data-testid="lineitem-form-unitprice"
197	          placeholder="Price each"
198	          value={unitPrice}
199	          onChange={(e) => setUnitPrice(e.target.value)}
200	        />
201	        <button data-testid="lineitem-form-submit" type="submit">
202	          Add line item
203	        </button>
204	      </form>
205	    </section>
206	  );
207	}
208	
209	// A project's detail: its invoices, what they add up to, and a form to add a new invoice. Owns its
210	// own invoice state, scoped to the one project it is showing.
211	function ProjectDetail({ project }: { project: Project }) {
212	  const [invoices, setInvoices] = useState<Invoice[]>([]);
213	  const [tasks, setTasks] = useState<Task[]>([]);
214	  const [amount, setAmount] = useState('');
215	  const [amountError, setAmountError] = useState('');
216	  const [sortByDue, setSortByDue] = useState(false);
217	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
218	
219	  async function load() {
220	    const res = await fetch(`/api/invoices?projectId=${project.id}`);
221	    setInvoices(await res.json());
222	  }
223	
224	  async function loadTasks() {
225	    const res = await fetch(`/api/tasks?projectId=${project.id}`);
226	    setTasks(await res.json());
227	  }
228	
229	  useEffect(() => {
230	    void load();
231	    void loadTasks();
232	  }, [project.id]);
233	
234	  async function toggleTask(id: number) {
235	    await fetch(`/api/tasks/${id}/toggle`, { method: 'POST' });
236	    await loadTasks();
237	  }
238	
239	  async function submit(e: React.FormEvent) {
240	    e.preventDefault();
241	    const value = Number(amount);
242	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
243	      setAmountError('Amount must be more than zero');
244	      return;
245	    }
246	    setAmountError('');
247	    await fetch('/api/invoices', {
248	      method: 'POST',
249	      headers: { 'Content-Type': 'application/json' },
250	      body: JSON.stringify({ projectId: project.id, amount: Number(amount) }),
251	    });
252	    setAmount('');
253	    await load();
254	  }
255	
256	  async function send(id: number) {
257	    await fetch(`/api/invoices/${id}/send`, { method: 'POST' });
258	    await load();
259	  }
260	
261	  async function pay(id: number) {
262	    await fetch(`/api/invoices/${id}/pay`, { method: 'POST' });
263	    await load();
264	  }
265	
266	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
267	  const shownInvoices = sortByDue
268	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
269	    : invoices;
270	
271	  return (
272	    <section data-testid="project-detail">
273	      <h2 data-testid="project-detail-name">{project.name}</h2>
274	
275	      <table data-testid="project-tasks-table">
276	        <tbody>
277	          {tasks.map((t) => (
278	            <tr key={t.id} data-testid={`task-row-${t.id}`}>
279	              <td data-testid="task-title">{t.title}</td>
280	              <td data-testid="task-status">{t.done ? 'DONE' : 'OPEN'}</td>
281	              <td>
282	                <button data-testid={`task-toggle-${t.id}`} onClick={() => toggleTask(t.id)}>
283	                  {t.done ? 'Reopen' : 'Tick off'}
284	                </button>
285	              </td>
286	            </tr>
287	          ))}
288	        </tbody>
289	      </table>
290	
291	      <form data-testid="invoice-form" onSubmit={submit}>
292	        <input
293	          data-testid="invoice-form-amount"
294	          placeholder="Amount"
295	          value={amount}
296	          onChange={(e) => setAmount(e.target.value)}
297	        />
298	        <button data-testid="invoice-form-submit" type="submit">
299	          Add invoice
300	        </button>
301	        {amountError && (
302	          <p data-testid="invoice-form-amount-error" role="alert">
303	            {amountError}
304	          </p>
305	        )}
306	      </form>
307	
308	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
309	        Sort by due date
310	      </button>
311	
312	      {openInvoiceId === null ? (
313	        <>
314	          <table data-testid="project-invoices-table">
315	            <tbody>
316	              {shownInvoices.map((inv) => (
317	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
318	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
319	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
320	                  <td data-testid="invoice-due">{inv.dueDate}</td>
321	                  <td data-testid="invoice-status">{inv.status}</td>
322	                  <td>
323	                    <button
324	                      data-testid={`invoice-open-${inv.id}`}
325	                      onClick={() => setOpenInvoiceId(inv.id)}
326	                    >
327	                      Open
328	                    </button>
329	                    {inv.status === 'DRAFT' && (
330	                      <button data-testid={`invoice-send-${inv.id}`} onClick={() => send(inv.id)}>
331	                        Send
332	                      </button>
333	                    )}
334	                    {inv.status === 'SENT' && (
335	                      <button data-testid={`invoice-pay-${inv.id}`} onClick={() => pay(inv.id)}>
336	                        Mark paid
337	                      </button>
338	                    )}
339	                  </td>
340	                </tr>
341	              ))}
342	            </tbody>
343	          </table>
344	
345	          <p data-testid="project-invoices-total">{money(total)}</p>
346	        </>
347	      ) : (
348	        <InvoiceDetail
349	          invoiceId={openInvoiceId}
350	          onChange={load}
351	          onClose={() => setOpenInvoiceId(null)}
352	        />
353	      )}
354	    </section>
355	  );
356	}
357	
358	function ProjectsPage() {
359	  const [projects, setProjects] = useState<Project[]>([]);
360	  const [clients, setClients] = useState<Client[]>([]);
361	  const [name, setName] = useState('');
362	  const [clientId, setClientId] = useState('');
363	  const [openId, setOpenId] = useState<number | null>(null);
364	
365	  async function loadProjects() {
366	    const res = await fetch('/api/projects');
367	    setProjects(await res.json());
368	  }
369	
370	  async function loadClients() {
371	    const res = await fetch('/api/clients');
372	    setClients(await res.json());
373	  }
374	
375	  useEffect(() => {
376	    void loadProjects();
377	    void loadClients();
378	  }, []);
379	
380	  async function submit(e: React.FormEvent) {
381	    e.preventDefault();
382	    if (!name.trim() || !clientId) {
383	      return;
384	    }
385	    await fetch('/api/projects', {
386	      method: 'POST',
387	      headers: { 'Content-Type': 'application/json' },
388	      body: JSON.stringify({ name, clientId: Number(clientId) }),
389	    });
390	    setName('');
391	    setClientId('');
392	    await loadProjects();
393	  }
394	
395	  const open = projects.find((p) => p.id === openId) ?? null;
396	
397	  return (
398	    <section data-testid="projects">
399	      <form data-testid="project-form" onSubmit={submit}>
400	        <input
401	          data-testid="project-form-name"
402	          placeholder="Project name"
403	          value={name}
404	          onChange={(e) => setName(e.target.value)}
405	        />
406	        <select
407	          data-testid="project-form-client"
408	          value={clientId}
409	          onChange={(e) => setClientId(e.target.value)}
410	        >
411	          <option value="">Select a client</option>
412	          {clients.map((c) => (
413	            <option key={c.id} value={String(c.id)}>
414	              {c.name}
415	            </option>
416	          ))}
417	        </select>
418	        <button data-testid="project-form-submit" type="submit">
419	          Add project
420	        </button>
421	      </form>
422	
423	      {projects.length === 0 ? (
